630: inline double log_split_lognormal_density(double v, double mu, double sigma,
631:                                           double delta) {
632:   if (delta == 0.0) return dlnorm_std(v, mu, sigma, true);
633:   if (!(v > 0.0)) return R_NegInf;
634:   split_lognormal_shape h;
635:   if (!split_lognormal_shape_params(mu, sigma, delta, h)) return R_NegInf;
636:   const double x = std::log(v);
637:   const double s = (x <= h.c) ? h.sL : h.sR;
638:   const double mass = (x <= h.c) ? h.a : (1.0 - h.a);
639:   return std::log(2.0 * mass) - std::log(s) - std::log(v) -
640:     0.5 * (x - h.c) * (x - h.c) / (s * s) - LOG_SQRT_2PI;
641: }
642: inline double log_split_lognormal_cdf(double v, double mu, double sigma,
643:                                       double delta) {
644:   if (delta == 0.0) return pnorm_log_direct((std::log(v) - mu) / sigma, true);
645:   if (!(v > 0.0)) return R_NegInf;
646:   split_lognormal_shape h;
647:   if (!split_lognormal_shape_params(mu, sigma, delta, h)) return R_NegInf;
648:   const double x = std::log(v);
649:   if (x <= h.c) {
650:     // Below the split point the CDF reduces to 2*a*Phi((x - c) / sigma_L)
651:     // exactly, so evaluate it directly: complementing the survivor here
652:     // rounds deep-left tail masses to zero even while still representable.
653:     const double z = (x - h.c) / h.sL;
654:     return std::fmin(std::log(2.0 * h.a) + pnorm_log_direct(z, true), 0.0);
655:   }
656:   const double ls = log_split_lognormal_survivor(v, mu, sigma, delta);
657:   return (ls < 0.0) ? log1m_exp(ls) : R_NegInf;
658: }
659: 
660: // A natural probability difference is rejected once it retains less than
661: // EMC2_NAT_REL_CANCEL of its largest term; a natural CDF consumed as
662: // log(1 - F) is rejected within EMC2_CDF_SAT_MARGIN of one; signed-log
663: // brackets are trusted while they keep log(1e-6) of their largest term.
664: constexpr double EMC2_NAT_REL_CANCEL = 1e-10;
665: constexpr double EMC2_CDF_SAT_MARGIN = 1e-8;
666: constexpr double EMC2_LOG_CANCEL_MIN = -13.815510557964274;  // log(1e-6)
