668: // Fast log-normal CDF/PDF wrappers.
669: // For sdlog <= 0 or non-finite sdlog, fall back to R's implementation to preserve semantics.
670: inline double plnorm_std(double x, double meanlog, double sdlog,
671:                          bool lower_tail = true, bool log_p = false) {
672:   if (x <= 0.0) {
673:     if (log_p) return lower_tail ? R_NegInf : 0.0;
674:     return lower_tail ? 0.0 : 1.0;
675:   }
676:   if (!emc2_isfinite(sdlog) || !(sdlog > 0.0)) {
677:     return R::plnorm(x, meanlog, sdlog, lower_tail, log_p);
678:   }
679:   const double z = (std::log(x) - meanlog) / sdlog;
680:   return pnorm_std(z, lower_tail, log_p);
681: }
682: 
683: inline double dlnorm_std(double x, double meanlog, double sdlog,
684:                          bool log_p = false) {
685:   if (x <= 0.0) return log_p ? R_NegInf : 0.0;
686:   if (!emc2_isfinite(sdlog) || !(sdlog > 0.0)) {
687:     return R::dlnorm(x, meanlog, sdlog, log_p);
688:   }
689:   const double z = (std::log(x) - meanlog) / sdlog;
690:   const double log_pdf = -std::log(x) - std::log(sdlog) - 0.5 * z * z - LOG_SQRT_2PI;
691:   return log_p ? log_pdf : std::exp(log_pdf);
692: }
693: 
694: inline double lnorm_log_surv_std(double x, double meanlog, double sdlog) {
695:   if (x <= 0.0) return 0.0;
696:   if (!emc2_isfinite(sdlog) || !(sdlog > 0.0)) {
697:     const double cdf = R::plnorm(x, meanlog, sdlog, true, false);
698:     if (cdf >= 1.0) return R_NegInf;
699:     if (cdf <= 0.0) return 0.0;
700:     return std::log1p(-cdf);
701:   }
702:   const double z = (std::log(x) - meanlog) / sdlog;
703:   // Extended tail: keep the log survivor finite past the fast path's z = 37
704:   // cutoff instead of collapsing far-tail races to -Inf.
705:   return pnorm_log_direct(z, false);
706: }
707: 
708: inline double pigt0(double t, double k, double l){
709:   if (l == 0.0) return 2.0 * pnorm_std(-k / std::sqrt(t), true, false);
710:   double mu = k / l;
711:   double lambda = k * k;
712: 
713:   double p1 = pnorm_std(std::sqrt(lambda/t) * (1. + t/mu), false, true);
714:   double p2 = pnorm_std(std::sqrt(lambda/t) * (1. - t/mu), false, false);
715: 
716:   return std::exp(2.0 * k * l + p1) + p2;
717: }
718: 
719: inline double digt0(double t, double k, double l){
720:   double lambda = k * k;
721:   double e;
722:   if (l == 0.) {
723:     e = -.5 * lambda / t;
724:   } else {
725:     double mu = k / l;
726:     e = - (lambda / (2. * t)) * ((t * t) / (mu * mu) - 2. * t / mu + 1.);
727:   }
728:   return std::exp(e + .5 * std::log(lambda) - .5 * std::log(2. * t * t * t * M_PI));
729: }
730: 
731: inline double pigt_impl(double t, double k = 1, double l = 1, double a = .1, double threshold = 1e-10){
732:   if (t <= 0.) return 0.;
733:   if (a < threshold) return pigt0(t, k, l);
734: 
735:   const double sqt = std::sqrt(t);
736: 
737:   if (std::abs(l) < threshold) {
738:     const double p1 = pnorm_std((k + a) / sqt, true, false);
739:     const double p2 = pnorm_std((k - a) / sqt, true, false);
740:     const double diff_sq = (k + a) * (k + a) - (k - a) * (k - a);
741:     const double t1 = sqt * std::exp(-0.5 * (k - a) * (k - a) / t) * (-std::expm1(-0.5 * diff_sq / t)) / FAST_NORM_RT2PI;
742:     return (t1 + (k + a) * (1.0 - p1) - (k - a) * (1.0 - p2)) / a;
743:   }
744: 
745:   const double t1a = std::exp(- .5 * (k - a - t * l) * (k - a - t * l) / t);
746:   const double t1b = std::exp(- .5 * (a + k - t * l) * (a + k - t * l) / t);
747:   const double t1 = sqt * (t1a - t1b) / FAST_NORM_RT2PI;
748: 
749:   const double t2a = std::exp(2. * l * (k - a) + pnorm_std(- (k - a + t * l) / sqt, true, true));
750:   const double t2b = std::exp(2. * l * (k + a) + pnorm_std(- (k + a + t * l) / sqt, true, true));
