431: // --------------------------------------------------------------------------
432: // Continuous split-lognormal launch primitives.  Let Y = log(V) have split
433: // point c and widths sL,sR, with a=sL/(sL+sR).  Each side is a half-normal
434: // piece with total mass 2a and 2(1-a).  The location parameter mu is the
435: // median; c is solved from the closed-form median equations below.
436: // --------------------------------------------------------------------------
437: struct split_lognormal_shape {
438:   double c = 0.0;
439:   double sL = 0.0;
440:   double sR = 0.0;
441:   double a = 0.5;
442: };
443: 
444: inline bool split_lognormal_shape_params(double mu, double sigma, double delta,
445:                                          split_lognormal_shape& h) {
446:   if (!(sigma > 0.0) || !emc2_isfinite(mu) || !emc2_isfinite(delta))
447:     return false;
448:   if (delta == 0.0) {
449:     h.c = mu; h.sL = sigma; h.sR = sigma; h.a = 0.5;
450:     return true;
451:   }
452:   h.sL = sigma * std::exp(0.5 * delta);
453:   h.sR = sigma * std::exp(-0.5 * delta);
454:   if (!(h.sL > 0.0) || !(h.sR > 0.0) ||
455:       !emc2_isfinite(h.sL) || !emc2_isfinite(h.sR)) return false;
456:   h.a = 1.0 / (1.0 + std::exp(-delta));
457:   if (delta > 0.0)
458:     h.c = mu - h.sL * R::qnorm(1.0 / (4.0 * h.a), 0.0, 1.0, true, false);
459:   else
460:     h.c = mu - h.sR * R::qnorm((3.0 * h.sR - h.sL) /
461:                                (4.0 * h.sR), 0.0, 1.0, true, false);
462:   return emc2_isfinite(h.c);
463: }
