465: inline double split_lognormal_log_side_tail(double x, double r,
466:                                             const split_lognormal_shape& h,
467:                                             bool left) {
468:   const double s = left ? h.sL : h.sR;
469:   const double mass = left ? h.a : (1.0 - h.a);
470:   const double base = std::log(2.0 * mass) + r * h.c + 0.5 * r * r * s * s;
471:   if (left) {
472:     if (!(x < h.c)) return R_NegInf;
473:     const double lo = (x - h.c - r * s * s) / s;
474:     const double hi = -r * s;
475:     return base + log_normal_interval(lo, hi);
476:   }
477:   const double lo = (x > h.c) ? (x - h.c - r * s * s) / s : -r * s;
478:   return base + log_normal_upper_tail(lo);
479: }
