502: // Direct launch-CDF integral for the BAwL survivor.  Unlike complementing the
503: // CDF, this remains accurate when all start points have essentially crossed.
504: inline double log_bawl_surv_normal(double t, double A, double b, double v,
505:                                    double sv, double k, bool posdrift,
506:                                    double denom_floor) {
507:   if (!(t > 0.0) || !(sv > 0.0)) return R_NegInf;
508:   const BawlLaunchGeom g = bawl_launch_geom(t, A, b, k);
509:   if (!g.ok) return R_NegInf;
510:   const double log_denom = log_positive_normalizer(v, sv, posdrift, denom_floor);
511:   if (g.frozen || A <= BAWL_A_EPS || !(g.width > 0.0)) {
512:     const double w = g.frozen ? k * b : g.w_hi;
513:     return std::fmin(log_normal_cdf_positive(w, v, sv, posdrift, denom_floor), 0.0);
514:   }
515:   const double li = log_normal_phi_integral_positive_raw(
516:     (g.w_lo - v) / sv, (g.w_hi - v) / sv, v, sv, posdrift);
517:   if (!(li > R_NegInf)) return R_NegInf;
518:   const double out = g.log_s - std::log(A) + std::log(sv) + li - log_denom;
519:   return std::fmin(out, 0.0);
520: }
